"""Synthetic service history of invented people across several orders: three enrollments, departure for the SVO zone,
missing in action with exclusion from the lists, an appointment to a post after the last movement (names invented)."""
import sys,os
from docx import Document
OUT=(sys.argv[1] if len(sys.argv)>1 else 'histcases').rstrip('/')+'/';os.makedirs(OUT,exist_ok=True)
SIGN=['','КОМАНДИР ВОЙСКОВОЙ ЧАСТИ 44444','полковник','А.Энский']
def order(num,date,dd,body,sign=True):
  d=Document()
  for t in ['ПРИКАЗ','КОМАНДИРА ВОЙСКОВОЙ ЧАСТИ 44444','по строевой части',f'« {dd} » {date} г. № {num}','г. Энск','']+body+(SIGN if sign else []):
    d.add_paragraph(t)
  return d
d=order(203,'сентября 2022','27',['§ 20','Нижепоименованный личный состав, призванный на военную службу по мобилизации, зачислить в списки личного состава воинской части с 27 сентября 2022 года:'],sign=False)
tb=d.add_table(rows=1,cols=3);h=tb.rows[0].cells;h[0].text='№ п/п';h[1].text='Фамилия, имя, отчество';h[2].text='Личный номер'
for i,n in enumerate(['Алмазов Иван Иванович','Солнцев Иван Валерьевич','Берёзов Олег Петрович','Ветлугин Роман Андреевич']):
  c=tb.add_row().cells;c[0].text=str(i+1);c[1].text=n;c[2].text=f'ЖК-{500100+i}'
d.add_paragraph('Основание: именной список военного комиссариата.')
for t in SIGN:d.add_paragraph(t)
d.save(OUT+'Приказ 203 от 27.09.2022.docx')
